/**
 * @fileoverview A package whose function calls itself `depth` times before it runs the callback it was given.
 * @module deep-walker
 */

/**
 * Call `callback` from `depth` frames of this function.
 * @param {number} depth - How many times to recurse first.
 * @param {Function} callback - What to call at the bottom.
 * @returns {*} What the callback returns.
 * @example
 * descend(60, () => "done"); // "done"
 */
export function descend(depth, callback) {
	return depth > 0 ? descend(depth - 1, callback) : callback();
}
